
"use strict";

// =====================================
// MINIFEED - REDE SOCIAL
// Projeto somente em JavaScript
// =====================================

// Banco de dados temporário
const usuarios = [
    {
            id: 1,
                    nome: "Ana Silva",
                            seguidores: 120,
                                    seguindo: 85
                                        },
                                            {
                                                    id: 2,
                                                            nome: "Pedro Santos",
                                                                    seguidores: 250,
                                                                            seguindo: 110
                                                                                },
                                                                                    {
                                                                                            id: 3,
                                                                                                    nome: "Julia Costa",
                                                                                                            seguidores: 180,
                                                                                                                    seguindo: 95
                                                                                                                        }
                                                                                                                        ];

                                                                                                                        let publicacoes = [
                                                                                                                            {
                                                                                                                                    id: 1,
                                                                                                                                            usuarioId: 1,
                                                                                                                                                    texto: "Hoje foi um dia incrível! 😊",
                                                                                                                                                            curtidas: [],
                                                                                                                                                                    comentarios: []
                                                                                                                                                                        },
                                                                                                                                                                            {
                                                                                                                                                                                    id: 2,
                                                                                                                                                                                            usuarioId: 2,
                                                                                                                                                                                                    texto: "Qual é o seu jogo favorito? 🎮",
                                                                                                                                                                                                            curtidas: [],
                                                                                                                                                                                                                    comentarios: []
                                                                                                                                                                                                                        },
                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                    id: 3,
                                                                                                                                                                                                                                            usuarioId: 3,
                                                                                                                                                                                                                                                    texto: "Nunca desista dos seus sonhos! ✨",
                                                                                                                                                                                                                                                            curtidas: [],
                                                                                                                                                                                                                                                                    comentarios: []
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                        ];

                                                                                                                                                                                                                                                                        // =====================================
                                                                                                                                                                                                                                                                        // ENCONTRAR USUÁRIO
                                                                                                                                                                                                                                                                        // =====================================

                                                                                                                                                                                                                                                                        function encontrarUsuario(id) {
                                                                                                                                                                                                                                                                            return usuarios.find(usuario => usuario.id === id);
                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                            // =====================================
                                                                                                                                                                                                                                                                            // CRIAR PUBLICAÇÃO
                                                                                                                                                                                                                                                                            // =====================================

                                                                                                                                                                                                                                                                            function criarPublicacao(usuarioId, texto) {
                                                                                                                                                                                                                                                                                const usuario = encontrarUsuario(usuarioId);

                                                                                                                                                                                                                                                                                    if (!usuario) {
                                                                                                                                                                                                                                                                                            console.log("Usuário não encontrado.");
                                                                                                                                                                                                                                                                                                    return null;
                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                            if (!texto || texto.trim() === "") {
                                                                                                                                                                                                                                                                                                                    console.log("A publicação não pode estar vazia.");
                                                                                                                                                                                                                                                                                                                            return null;
                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                    const novaPublicacao = {
                                                                                                                                                                                                                                                                                                                                            id: Date.now(),
                                                                                                                                                                                                                                                                                                                                                    usuarioId: usuarioId,
                                                                                                                                                                                                                                                                                                                                                            texto: texto.trim(),
                                                                                                                                                                                                                                                                                                                                                                    curtidas: [],
                                                                                                                                                                                                                                                                                                                                                                            comentarios: []
                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                    publicacoes.unshift(novaPublicacao);

                                                                                                                                                                                                                                                                                                                                                                                        console.log("Publicação criada com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                            return novaPublicacao;
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                            // =====================================
                                                                                                                                                                                                                                                                                                                                                                                            // MOSTRAR FEED
                                                                                                                                                                                                                                                                                                                                                                                            // =====================================

                                                                                                                                                                                                                                                                                                                                                                                            function mostrarFeed() {
                                                                                                                                                                                                                                                                                                                                                                                                console.log("===== FEED DO MINIFEED =====");

                                                                                                                                                                                                                                                                                                                                                                                                    publicacoes.forEach(publicacao => {
                                                                                                                                                                                                                                                                                                                                                                                                            const usuario = encontrarUsuario(publicacao.usuarioId);

                                                                                                                                                                                                                                                                                                                                                                                                                    console.log("----------------------------");
                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Autor:", usuario.nome);
                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log("Publicação:", publicacao.texto);
                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Curtidas:", publicacao.curtidas.length);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log("Comentários:", publicacao.comentarios.length);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("============================");
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                            // CURTIR OU REMOVER CURTIDA
                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                            function curtirPublicacao(publicacaoId, usuarioId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                const publicacao = publicacoes.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        item => item.id === publicacaoId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!publicacao || !encontrarUsuario(usuarioId)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log("Publicação ou usuário não encontrado.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const indice = publicacao.curtidas.indexOf(usuarioId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (indice === -1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    publicacao.curtidas.push(usuarioId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Você curtiu a publicação! ❤️");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        publicacao.curtidas.splice(indice, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log("Curtida removida.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ADICIONAR COMENTÁRIO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function comentar(publicacaoId, usuarioId, texto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const publicacao = publicacoes.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                item => item.id === publicacaoId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const usuario = encontrarUsuario(usuarioId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!publicacao || !usuario) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log("Publicação ou usuário não encontrado.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!texto || texto.trim() === "") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Digite um comentário.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            publicacao.comentarios.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    usuarioId: usuarioId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            texto: texto.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    data: new Date().toLocaleString("pt-BR")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Comentário adicionado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // VER COMENTÁRIOS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function mostrarComentarios(publicacaoId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const publicacao = publicacoes.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        item => item.id === publicacaoId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!publicacao) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log("Publicação não encontrada.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        publicacao.comentarios.forEach(comentario => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const usuario = encontrarUsuario(comentario.usuarioId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    usuario.nome + ": " + comentario.texto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // PESQUISAR PUBLICAÇÕES
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function pesquisarPublicacoes(termo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const pesquisa = termo.toLowerCase().trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const resultados = publicacoes.filter(publicacao =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                publicacao.texto.toLowerCase().includes(pesquisa)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log("Resultados encontrados:", resultados.length);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return resultados;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // MOSTRAR PERFIL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function mostrarPerfil(usuarioId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const usuario = encontrarUsuario(usuarioId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!usuario) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Perfil não encontrado.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const totalPublicacoes = publicacoes.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    item => item.usuarioId === usuarioId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ).length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("===== PERFIL =====");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log("Nome:", usuario.nome);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log("Seguidores:", usuario.seguidores);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log("Seguindo:", usuario.seguindo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Publicações:", totalPublicacoes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // SEGUIR USUÁRIO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function seguirUsuario(seguidorId, seguidoId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const seguidor = encontrarUsuario(seguidorId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const seguido = encontrarUsuario(seguidoId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!seguidor || !seguido) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log("Usuário não encontrado.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (seguidorId === seguidoId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log("Você não pode seguir a si mesmo.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        seguido.seguidores++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            seguidor.seguindo++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log("Agora você está seguindo " + seguido.nome);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // EXEMPLOS DE USO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Mostrar publicações:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarFeed();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Criar uma publicação:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // criarPublicacao(1, "Olá, pessoal!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Curtir uma publicação:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // curtirPublicacao(1, 2);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Comentar uma publicação:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // comentar(1, 2, "Muito legal!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Ver comentários:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // mostrarComentarios(1);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Pesquisar publicações:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // console.log(pesquisarPublicacoes("jogo"));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Ver perfil:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // mostrarPerfil(1);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Seguir alguém:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // seguirUsuario(1, 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                